private String parseToken(final char[] terminators) {
    // Initialize the token to an empty string
    String token = "";

    // Loop through the input string
    for (int i = 0; i < input.length(); i++) {
        // Get the current character
        char c = input.charAt(i);

        // Check if the current character is a terminator
        for (char terminator : terminators) {
            if (c == terminator) {
                // If it is a terminator, return the token
                return token;
            }
        }

        // If the current character is not a terminator, add it to the token
        token += c;
    }

    // If we reach the end of the input string without finding a terminator, return the token
    return token;
